packages/eslint-plugin-mobx/__tests__/unconditional-make-observable.js::unconditional-make-observable::invalid::
class C {
  constructor() {    
    if (true) {
      makeObservable(this, {});
      makeAutoObservable(this, {});
    }
    for (let i = 0; i < 1; i++) {
      makeObservable(this, {});
      makeAutoObservable(this, {});
    }
    while (Math.random() > 1) {
      makeObservable(this, {});
      makeAutoObservable(this, {});
    }
    const a = () => {
      makeObservable(this, {});
    }
  }    
}

packages/eslint-plugin-mobx/__tests__/unconditional-make-observable.js::unconditional-make-observable::valid::
class C {
  constructor() {
    makeObservable()
    makeObservable({})
    makeObservable(this)
    function f() {
      makeObservable(this, {});
    }
    const ff = function () {
      makeObservable(this, {});
    }
  }    
}
